<script setup lang="ts">
import { ref, watch, onBeforeUnmount } from 'vue';import { Head } from '@inertiajs/vue3';import { locale } from '../../i18n';import SiteHeader from '../../components/website/SiteHeader.vue';import SiteFooter from '../../components/website/SiteFooter.vue';import Icon from '../../components/website/Icon.vue';import type { SiteDocument } from '../../components/website/types';defineProps<{navigation:SiteDocument;domainRoot:string}>();const tr=(id:string,en:string)=>locale.value==='id'?id:en;
const form=ref({name:'',email:'',phone:'',business_type:'retail',subdomain:'',consent:false,marketing_consent:false,website:''}),busy=ref(false),done=ref(false),error=ref('');
const domainState=ref('idle'),suggestions=ref<string[]>([]);let domainTimer:ReturnType<typeof setTimeout>|undefined;let domainRequest:AbortController|undefined;let domainSequence=0;
watch(()=>form.value.subdomain,value=>{const sequence=++domainSequence;clearTimeout(domainTimer);domainRequest?.abort();suggestions.value=[];domainState.value='idle';if(!/^[a-z][a-z0-9-]{2,39}$/.test(value)||value.endsWith('-')||value.includes('--')){if(value)domainState.value='invalid';return;}domainState.value='checking';domainTimer=setTimeout(async()=>{const controller=new AbortController();domainRequest=controller;const timeout=setTimeout(()=>controller.abort(),8000);try{const r=await fetch('/register/subdomain?slug='+encodeURIComponent(value),{headers:{Accept:'application/json'},signal:controller.signal,cache:'no-store'});const data=await r.json();if(sequence!==domainSequence)return;if(!r.ok)throw Error();domainState.value=data.available?'available':'unavailable';suggestions.value=data.suggestions??[];}catch{if(sequence===domainSequence)domainState.value='error';}finally{clearTimeout(timeout);}},400);});
onBeforeUnmount(()=>{clearTimeout(domainTimer);domainRequest?.abort();});
const resendEmail=ref(''),resendConsent=ref(false),resendDone=ref(false);
async function resend(){if(busy.value)return;busy.value=true;error.value='';try{const r=await fetch('/register/resend',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json',Accept:'application/json','X-CSRF-TOKEN':document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content??''},body:JSON.stringify({email:resendEmail.value,consent:resendConsent.value}),signal:AbortSignal.timeout(25000)});if(!r.ok)throw Error();resendDone.value=true;}catch{error.value=tr('Permintaan belum berhasil. Coba lagi beberapa menit lagi.','The request did not complete. Try again in a few minutes.');}finally{busy.value=false;}}
async function submit(){if(busy.value||domainState.value!=='available')return;busy.value=true;error.value='';try{const r=await fetch('/register',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json',Accept:'application/json','X-CSRF-TOKEN':document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content??''},body:JSON.stringify({...form.value,locale:locale.value}),signal:AbortSignal.timeout(25000)});const data=await r.json();if(!r.ok)throw new Error(data.code??String(r.status));if(data.status!=='received')throw new Error();done.value=true;}catch(e){error.value=e instanceof Error&&e.message==='EMAIL_ALREADY_REGISTERED'?tr('Email ini sudah terdaftar. Gunakan halaman masuk atau kirim ulang verifikasi di bawah.','This email is already registered. Sign in or resend verification below.'):e instanceof Error&&e.message==='429'?tr('Terlalu banyak permintaan. Silakan coba lagi nanti.','Too many requests. Please try later.'):tr('Pendaftaran belum terkonfirmasi. Periksa isian atau ulangi dengan email yang sama.','Registration is not confirmed. Check your details or retry using the same email.');}finally{busy.value=false;}}
</script>
<template><div class="oneqay-site"><Head :title="tr('Daftarkan bisnis | oneQay','Register your business | oneQay')"/><SiteHeader :navigation="navigation"/><main class="register-wrap wrap"><div class="register-intro"><p class="site-eyebrow"><span></span>{{ tr('LANGKAH PERTAMA ANDA','YOUR FIRST STEP') }}</p><h1>{{ tr('Bisnis Anda.\nRuang tumbuh baru.','Your business.\nA new space to grow.') }}</h1><p>{{ tr('Ceritakan sedikit tentang bisnis Anda. Tautan verifikasi dikirim ke email Anda. Setelah verifikasi dan pembuatan kata sandi, akun admin bisnis langsung aktif tanpa persetujuan manual. Saat ini gratis.','Tell us a little about your business. Verify your email and set your password to activate your business administrator account without manual approval. Currently free.') }}</p><ol><li><b>01</b><div><strong>{{ tr('Daftarkan bisnis','Register your business') }}</strong><p>{{ tr('Gunakan email aktif yang Anda kuasai.','Use an active email that you control.') }}</p></div></li><li><b>02</b><div><strong>{{ tr('Verifikasi email','Verify email') }}</strong><p>{{ tr('Buka tautan email dan buat kata sandi Anda.','Open your email link and set your password.') }}</p></div></li><li><b>03</b><div><strong>{{ tr('Mulai operasional','Start operating') }}</strong><p>{{ tr('Siapkan produk, tim, dan hak akses.','Set up products, your team and access.') }}</p></div></li></ol></div><section class="registration-card"><div v-if="done" class="registration-success" role="status"><span class="success-check"><Icon name="check"/></span><h2>{{ tr('Periksa email Anda.','Check your email.') }}</h2><p>{{ tr('Tautan verifikasi sudah masuk ke antrean pengiriman. Periksa inbox dan folder spam. Tautan berlaku 24 jam. Setelah email diverifikasi dan kata sandi dibuat, akun langsung aktif tanpa approval.','Your verification link has been queued. Check your inbox and spam folder. The link expires in 24 hours. Verify your email and set a password to activate without approval.') }}</p><a class="site-btn" href="/business-login">{{ tr('Ke halaman masuk','Go to login') }}<Icon name="log-in"/></a><a class="site-text-link" href="/">{{ tr('Kembali ke beranda','Back to home') }}</a></div><form v-else @submit.prevent="submit"><h2>{{ tr('Mari mulai.','Let’s get started.') }}</h2><p>{{ tr('Lengkapi informasi bisnis Anda.','Enter your business information.') }}</p><p v-if="error" class="form-error" role="alert">{{ error }}</p><fieldset :disabled="busy"><label>{{ tr('Nama bisnis','Business name') }}<input v-model="form.name" required maxlength="160" autocomplete="organization"/></label><label>{{tr('Alamat bisnis permanen','Permanent business address')}}<input v-model="form.subdomain" required minlength="3" maxlength="40" pattern="[a-z][a-z0-9-]{2,39}" autocomplete="off" autocapitalize="none" spellcheck="false" :aria-invalid="['invalid','unavailable'].includes(domainState)"/><small>{{form.subdomain||'bisnis-anda'}}.{{domainRoot}}</small></label><p role="status">{{domainState==='available'?tr('✓ Nama tersedia','✓ Name available'):domainState==='unavailable'?tr('Nama tidak tersedia','Name unavailable'):domainState==='checking'?tr('Memeriksa…','Checking…'):domainState==='error'?tr('Pemeriksaan belum berhasil. Ubah isian untuk mencoba lagi.','Unable to check. Edit the name to retry.'):domainState==='invalid'?tr('Gunakan 3–40 huruf kecil, angka, atau tanda hubung.','Use 3–40 lowercase letters, digits, or hyphens.'):tr('Setelah terdaftar, alamat hanya dapat diubah pemilik platform.','After registration, only the platform owner can change this address.')}}</p><div v-if="domainState==='unavailable'" class="domain-suggestions"><button v-for="slug in suggestions" :key="slug" type="button" @click="form.subdomain=slug">{{slug}}</button></div><label>{{ tr('Email pemilik bisnis','Business owner email') }}<input v-model="form.email" type="email" required maxlength="254" autocomplete="email" placeholder="nama@bisnis.com"/></label><label>{{ tr('Nomor kontak','Contact number') }}<input v-model="form.phone" type="tel" inputmode="tel" required pattern="\+?[0-9 ]{7,23}" maxlength="24" autocomplete="tel" placeholder="+62 812 3456 7890"/></label><label>{{ tr('Jenis bisnis','Business type') }}<select v-model="form.business_type"><option value="retail">{{ tr('Toko ritel','Retail store') }}</option><option value="food">{{ tr('Makanan & minuman','Food & beverage') }}</option><option value="services">{{ tr('Jasa','Services') }}</option><option value="laundry">Laundry</option><option value="boarding">{{tr('Kosan','Boarding house')}}</option><option value="homestay">Homestay</option><option value="other">{{ tr('Lainnya','Other') }}</option></select></label><label class="honey" aria-hidden="true">Website<input v-model="form.website" tabindex="-1" autocomplete="off"/></label><label class="consent"><input v-model="form.consent" type="checkbox" required/><span>{{ tr('Saya menyetujui','I agree to the') }} <a href="/pages/terms" target="_blank" rel="noopener">{{ tr('ketentuan pendaftaran','registration terms') }}</a> {{ tr('dan','and') }} <a href="/pages/privacy" target="_blank" rel="noopener">{{ tr('informasi privasi','privacy information') }}</a>.</span></label><label class="consent"><input v-model="form.marketing_consent" type="checkbox"/><span>{{ tr('Saya ingin menerima informasi produk dan penawaran oneQay melalui email (opsional).','I would like product news and offers from oneQay by email (optional).') }}</span></label><button class="site-btn" type="submit" :disabled="domainState!=='available'">{{ busy?tr('Mengirim…','Submitting…'):tr('Daftar gratis & verifikasi email','Register free & verify email') }}<Icon name="arrow-up-right"/></button></fieldset><p class="form-footnote">{{ tr('Sudah punya akun?','Already have an account?') }} <a href="/business-login">{{ tr('Masuk di sini','Log in here') }}</a></p></form><details class="verification-resend"><summary>{{tr('Tautan kedaluwarsa atau email belum diterima?','Expired link or missing verification email?')}}</summary><form @submit.prevent="resend"><p>{{tr('Kirim ulang ke email pendaftaran yang sama. Periksa juga folder spam. Tautan baru menggantikan tautan lama.','Resend to your registration email. Check spam too. A new link replaces the old one.')}}</p><label>Email<input v-model="resendEmail" type="email" required maxlength="254"/></label><label class="consent"><input v-model="resendConsent" type="checkbox" required/><span>{{tr('Saya menyetujui ketentuan dan privasi yang berlaku.','I agree to the current terms and privacy notice.')}} <a href="/pages/terms">{{tr('Baca ketentuan','Read terms')}}</a> · <a href="/pages/privacy">{{tr('Privasi','Privacy')}}</a></span></label><button class="site-btn" :disabled="busy">{{tr('Kirim ulang verifikasi','Resend verification')}}</button><p v-if="resendDone" role="status">{{tr('Jika email menunggu verifikasi, tautan baru masuk antrean. Akun aktif atau ditangguhkan tidak berubah.','If the email awaits verification, a new link is queued. Active or suspended accounts remain unchanged.')}}</p></form></details></section></main><SiteFooter :navigation="navigation"/></div></template>

<style scoped>.verification-resend{border-top:1px solid #E9EBFF;margin-top:24px;padding-top:20px;color:#3965FA;font-size:14px}.verification-resend summary{cursor:pointer;font-weight:600}.verification-resend p{line-height:1.8}.verification-resend input[type=email]{width:100%;padding:12px;border:1px solid #99B7FC;border-radius:8px;margin:10px 0}.verification-resend .site-btn{font-size:14px}
